  "sol": "设 \\(BB'-CC'=100\\)，\\(C\\) 测 \\(B\\) 仰角 \\(15^{\\circ}\\)，则 \\(B'C'=\\frac{100}{\\tan15^{\\circ}}\\)。在 \\(\\triangle A'B'C'\\) 中，\\(\\angle A'C'B'=45^{\\circ}\\)，\\(\\angle A'B'C'=60^{\\circ}\\)，故 \\(\\angle B'A'C'=75^{\\circ}\\)，由正弦定理 \\(\\frac{A'B'}{\\sin45^{\\circ}}=\\frac{B'C'}{\\sin75^{\\circ}}\\)，得 \\(A'B'=\\frac{100\\cos15^{\\circ}\\cdot\\sin45^{\\circ}}{\\sin75^{\\circ}}=\\frac{50\\sqrt{2}}{\\sin75^{\\circ}}\\approx273\\)。\\(B\\) 测 \\(A\\) 仰角 \\(45^{\\circ}\\)，故 \\(AA'-BB'=A'B'\\approx273\\)。因此 \\(AA'-CC'=(BB'-CC')+(AA'-BB')=100+273=373\\)。"
