  "sol": "(1) \\(\\bar{x}=10\\)，\\(\\bar{y}=10.3\\)，\\(s_1^2=0.036\\)，\\(s_2^2=0.04\\)。(2) \\(\\bar{y}-\\bar{x}=0.3\\)，\\(2\\sqrt{\\dfrac{0.036+0.04}{10}}=2\\sqrt{0.0076}\\)，因 \\(0.3>2\\sqrt{0.0076}\\)，故新设备有显著提高。"
