  "stem": "如图，四棱锥 \\(P-ABCD\\) 的底面是矩形，\\(PD\\perp\\) 底面 \\(ABCD\\)，\\(M\\) 为 \\(BC\\) 的中点，且 \\(PB\\perp AM\\)。(1) 证明：平面 \\(PAM\\perp\\) 平面 \\(PBD\\)；(2) 若 \\(PD=DC=1\\)，求四棱锥 \\(P-ABCD\\) 的体积。",
