  "stem": "[选修4-4：坐标系与参数方程] 在直角坐标系 \\(xOy\\) 中，曲线 \\(C\\) 的参数方程为 \\(\\begin{cases}x=\\sqrt{3}\\cos 2t,\\\\ y=2\\sin t\\end{cases}\\)（\\(t\\) 为参数）。以坐标原点为极点，\\(x\\) 轴正半轴为极轴建立极坐标系，已知直线 \\(l\\) 的极坐标方程为 \\(\\rho\\sin\\left(\\theta+\\dfrac{\\pi}{3}\\right)+m=0\\)。（1）写出 \\(l\\) 的直角坐标方程；（2）若 \\(l\\) 与 \\(C\\) 有公共点，求 \\(m\\) 的取值范围。",
