  "stem": "已知 \\(f(x)=ax-\\dfrac{\\sin x}{\\cos^{3}x}\\)，\\(x\\in\\left(0,\\dfrac{\\pi}{2}\\right)\\)。（1）若 \\(a=8\\)，讨论 \\(f(x)\\) 的单调性；（2）若 \\(f(x)<\\sin 2x\\) 恒成立，求 \\(a\\) 的取值范围。",
