  "sol": "(1) 由 \\(A(-2,0)\\) 在 \\(C\\) 上得 \\(b=2\\)，又 \\(e=\\dfrac{c}{a}=\\dfrac{\\sqrt{5}}{3}\\)，\\(a^{2}=b^{2}+c^{2}\\)，解得 \\(a=3,b=2,c=\\sqrt{5}\\)，故 \\(C:\\dfrac{y^{2}}{9}+\\dfrac{x^{2}}{4}=1\\)。(2) 设 \\(PQ:y=k(x+2)+3\\)，联立椭圆得 \\((4k^{2}+9)x^{2}+8k(2k+3)x+16(k^{2}+3k)=0\\)，由韦达定理 \\(x_{1}+x_{2},x_{1}x_{2}\\)。\\(M\\left(0,\\dfrac{2y_{1}}{x_{1}+2}\\right)\\)，\\(N\\left(0,\\dfrac{2y_{2}}{x_{2}+2}\\right)\\)，计算 \\(\\dfrac{y_{M}+y_{N}}{2}=3\\) 为定值，故 \\(MN\\) 中点为定点 \\((0,3)\\)。"
