  "sol": "\\(z_{i}=x_{i}-y_{i}\\) 依次为 \\(9,6,8,-8,15,11,19,18,20,12\\)。\\(\\overline{z}=\\dfrac{9+6+8-8+15+11+19+18+20+12}{10}=11\\)。\\(s^{2}=\\dfrac{(-2)^{2}+(-5)^{2}+(-3)^{2}+(-19)^{2}+4^{2}+0^{2}+8^{2}+7^{2}+9^{2}+1^{2}}{10}=61\\)。又 \\(\\overline{z}=11\\geq2\\sqrt{\\dfrac{61}{10}}\\)，故认为有显著提高。"
