  "stem": "已知函数 \\(f(x)=\\sin x\\cos x+\\sqrt{3}\\cos^{2}x-\\dfrac{\\sqrt{3}}{2}\\)。\n(1) 求 \\(f(x)\\) 的最小正周期；\n(2) 求 \\(f(x)\\) 的单调递增区间。",
