  "stem": "已知等差数列 \\(\\{a_n\\}\\) 满足 \\(a_2=3\\)，\\(a_5=9\\)。\n(1) 求 \\(\\{a_n\\}\\) 的通项公式；\n(2) 求 \\(\\{a_n\\}\\) 的前 \\(n\\) 项和 \\(S_n\\)。",
