  "stem": "在 \\(\\triangle ABC\\) 中，\\(D\\) 为 \\(BC\\) 上一点，且 \\(BD:DC=1:2\\)。设 \\(\\overrightarrow{AB}=\\vec c\\)，\\(\\overrightarrow{AC}=\\vec b\\)。\n(1) 用 \\(\\vec b,\\vec c\\) 表示 \\(\\overrightarrow{AD}\\)；\n(2) 若 \\(E\\) 为 \\(AD\\) 的中点，用 \\(\\vec b,\\vec c\\) 表示 \\(\\overrightarrow{BE}\\)。",
