  "sol": "(1) \\(\\overrightarrow{AB}=B-A=(4-2,\\ 3-(-1))=(2,4)\\)，\\(|\\overrightarrow{AB}|=\\sqrt{2^{2}+4^{2}}=\\sqrt{20}=2\\sqrt{5}\\)。\n(2) 由 \\(\\overrightarrow{AC}=C-A=(-1,2)\\)，得 \\(C=A+(-1,2)=(2-1,\\ -1+2)=(1,1)\\)。\n(3) \\(\\overrightarrow{BC}=C-B=(1-4,\\ 1-3)=(-3,-2)\\)。判断 \\(\\overrightarrow{AB}=(2,4)\\) 与 \\(\\overrightarrow{BC}=(-3,-2)\\) 是否共线：\\(2\\times(-2)-4\\times(-3)=-4+12=8\\neq0\\)，故二者不共线。"
